/*insertMasterCmClClosingStndrdSetting*/

		INSERT INTO BILL_ACCOUNTING /* 회원사경리담당자관리 */
		(
		    ACCOUNTING_CODE
		  , SITE
		  , COM_CODE
		  , IRS_NO
		  , USER_NAME_LOC
		  , PHONE_NUMBER
		  , FAX_NUMBER
		  , EMAIL
		  , ZIP_CODE
		  , ADDRESS_LOC
		  , CREATE_USER_ID
		  , PRIORITY
		)
		VALUES
		(
		    (SELECT MAX(ACCOUNTING_CODE)+1 FROM BILL_ACCOUNTING)
		  , #{SYS_TYPE}
		  , #{COM_CODE}
		  , #{BUYER_IRS_NO}
		  , #{AC_USER_NAME} 
		  , #{AC_USER_PHONE} 
		  , #{AC_USER_FAX} 
		  , #{AC_USER_EMAIL} 
		  , #{AC_USER_ZIP} 
		  , #{AC_USER_ADD} 
		  , #{st_user_id} 
		  ,'Y'
		)

/*updateMasterCmClClosingStndrdSetting01*/

		UPDATE
		    BILL_ACCOUNTING /* 회원사경리담당자관리 */
		SET
		    USER_NAME_LOC   = #{AC_USER_NAME}
		  , PHONE_NUMBER    = #{AC_USER_PHONE}
		  , FAX_NUMBER      = #{AC_USER_FAX}
		  , EMAIL           = #{AC_USER_EMAIL}
		  , ZIP_CODE        = #{AC_USER_ZIP}
		  , ADDRESS_LOC     = #{AC_USER_ADD}
		  , CREATE_USER_ID  = #{st_user_id}
		WHERE
		    ACCOUNTING_CODE = #{AC_CODE}

/*updateMasterCmClClosingStndrdSetting02*/

		UPDATE 
		    ICOMCMPY /* 회원사정보 */
		SET	
		    CLOSE_CNT = #{CLOSE_CNT}
		  , BILL_TYPE = #{BILL_TYPE}
		  , BILL_CODE = #{BILL_CODE}
		WHERE 
		    COM_CODE  = #{COM_CODE}
